import os
from azure.core.credentials import AzureKeyCredential
from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.ai.documentintelligence.models import AnalyzeDocumentRequest, ContentFormat

def extract_expense_fields(document_content: bytes) -> dict:
    """
    Normalizes extracted expense fields into a standard JSON schema using Azure Document Intelligence.

    Args:
        document_content: The content of the document (e.g., PDF, JPG, PNG) as bytes.

    Returns:
        A dictionary representing the normalized expense fields.
    """
    endpoint = os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT")
    key = os.environ.get("AZURE_DOCUMENT_INTELLIGENCE_KEY")

    if not endpoint or not key:
        raise ValueError(
            "Please set the AZURE_DOCUMENT_INTELLIGENCE_ENDPOINT and "
            "AZURE_DOCUMENT_INTELLIGENCE_KEY environment variables."
        )

    document_intelligence_client = DocumentIntelligenceClient(
        endpoint=endpoint, credential=AzureKeyCredential(key)
    )

    poller = document_intelligence_client.begin_analyze_document(
        "prebuilt-invoice",
        AnalyzeDocumentRequest(bytes_data=document_content, content_format=ContentFormat.APPLICATION_OCTET_STREAM),
    )
    result = poller.result()

    normalized_expense = {
        "vendor_name": None,
        "total_amount": None,
        "currency": None,
        "invoice_date": None,
        "line_items": [],
    }

    if result.documents:
        invoice = result.documents[0]
        if invoice.fields:
            if "VendorName" in invoice.fields and invoice.fields["VendorName"].value:
                normalized_expense["vendor_name"] = invoice.fields["VendorName"].value
            if "InvoiceTotal" in invoice.fields and invoice.fields["InvoiceTotal"].value:
                normalized_expense["total_amount"] = invoice.fields["InvoiceTotal"].value.amount
                normalized_expense["currency"] = invoice.fields["InvoiceTotal"].value.currency_symbol
            if "InvoiceDate" in invoice.fields and invoice.fields["InvoiceDate"].value:
                normalized_expense["invoice_date"] = str(invoice.fields["InvoiceDate"].value)

            if "Items" in invoice.fields and invoice.fields["Items"].value:
                for item in invoice.fields["Items"].value:
                    line_item = {
                        "description": None,
                        "quantity": None,
                        "unit_price": None,
                        "total_price": None,
                    }
                    if "Description" in item.value and item.value["Description"].value:
                        line_item["description"] = item.value["Description"].value
                    if "Quantity" in item.value and item.value["Quantity"].value:
                        line_item["quantity"] = item.value["Quantity"].value
                    if "UnitPrice" in item.value and item.value["UnitPrice"].value:
                        line_item["unit_price"] = item.value["UnitPrice"].value.amount
                    if "Amount" in item.value and item.value["Amount"].value:
                        line_item["total_price"] = item.value["Amount"].value.amount
                    normalized_expense["line_items"].append(line_item)

    return normalized_expense
